package os.aios.agent;
import android.app.*;import android.content.*;import android.os.*;import org.json.*;
/** Real framework/Agent lock test using only the isolated counter fixture; no model simulation. */
public final class LockscreenDeviceTests extends Instrumentation {
 String mode="manual";AgentService agent;String id="",thread="combined-lock-test-thread";int assertions;StringBuilder log=new StringBuilder();
 void check(boolean ok,String message)throws Exception {if(!ok)throw new AssertionError(message);assertions++;log.append(message).append("\n");}
 public void onCreate(Bundle args){super.onCreate(args);mode=args.getString("mode","manual");start();}
 JSONObject call(String op)throws Exception{return agent.ui.call(new JSONObject().put("op",op).put("session_id",id));}
 void shell(String command)throws Exception{try(ParcelFileDescriptor p=getUiAutomation(UiAutomation.FLAG_DONT_SUPPRESS_ACCESSIBILITY_SERVICES).executeShellCommand(command);java.io.InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(p)){in.transferTo(java.io.OutputStream.nullOutputStream());}}
 JSONObject node(Object value,String text)throws Exception{if(value instanceof JSONObject){JSONObject j=(JSONObject)value;if(text.equals(j.optString("text")))return j;java.util.Iterator<String> keys=j.keys();while(keys.hasNext()){JSONObject found=node(j.get(keys.next()),text);if(found!=null)return found;}}else if(value instanceof JSONArray){JSONArray a=(JSONArray)value;for(int i=0;i<a.length();i++){JSONObject found=node(a.get(i),text);if(found!=null)return found;}}return null;}
 JSONObject observe()throws Exception{JSONObject result=null;for(int i=0;i<8;i++){result=call("tree");if(result.has("windows")&&node(result,"计数加一")!=null)return result;Thread.sleep(600);}throw new AssertionError("fixture tree unavailable: "+result);}
 // The fixture is recreated while locked: grant its system dialog before locking.
 // This clicks the normal user-authorized button, never changes framework permission state.
 void allowFixture(){android.view.accessibility.AccessibilityNodeInfo root=getUiAutomation(UiAutomation.FLAG_DONT_SUPPRESS_ACCESSIBILITY_SERVICES).getRootInActiveWindow();if(root==null||!"com.android.virtualdevicemanager".contentEquals(root.getPackageName())||root.findAccessibilityNodeInfosByText("AIOS combined verification").isEmpty())return;for(android.view.accessibility.AccessibilityNodeInfo n:root.findAccessibilityNodeInfosByText("始终允许")){for(int i=0;i<3&&n!=null;i++,n=n.getParent())if(n.isClickable()){n.performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_CLICK);return;}}}
 void create()throws Exception{JSONObject result=agent.ui.call(new JSONObject().put("op","create").put("package","os.aios.combined.tests"));log.append("create: ").append(result).append("\n");id=result.optString("session_id");check(!id.isEmpty(),"owned virtual session created");for(int i=0;i<240;i++){allowFixture();result=call("status");if("active".equals(result.optString("state")))return;Thread.sleep(500);}throw new AssertionError("native session not active: "+result);}
 void testMain()throws Exception{
  shell("am start -n os.aios.combined.tests/.CombinedFixtureActivity");Thread.sleep(1000);
  java.util.concurrent.FutureTask<JSONObject> task=new java.util.concurrent.FutureTask<>(()->agent.ui.foreground.create(new JSONObject().put("package","os.aios.combined.tests").put("_caller_thread",thread)));agent.ui.handler.post(task);JSONObject first=task.get(15,java.util.concurrent.TimeUnit.SECONDS);id=first.optString("session_id");check(!id.isEmpty(),"main lease created");JSONObject before=observe();check(before.getInt("display_id")==0,"main display observed");String token=before.getString("observation_id");
  shell("input keyevent KEYCODE_SLEEP");Thread.sleep(2200);JSONObject state=call("status");check("paused".equals(state.optString("state")),"running main lease pauses after lock");JSONObject read=call("tree");check(!read.optBoolean("executed")&&!read.has("windows"),"locked main observation denied");JSONObject input=agent.ui.call(new JSONObject().put("op","tap").put("session_id",id).put("observation_id",token).put("x",60).put("y",180));check(!input.optBoolean("executed"),"pre-lock main input credential rejected");check(!state.optBoolean("foreground"),"no main app input while keyguard owns display");
 }
 public void onStart(){Bundle result=new Bundle();int code=-1;Context c=getTargetContext();try{
  c.startForegroundService(new Intent(c,AgentService.class));for(int i=0;i<40&&AgentService.instance==null;i++)Thread.sleep(250);agent=AgentService.instance;if(agent==null)throw new AssertionError("Agent service unavailable");
  java.util.concurrent.FutureTask<Void> clean=new java.util.concurrent.FutureTask<>(()->{for(UiSessionController old:new java.util.ArrayList<>(agent.ui.sessions.values()))if("os.aios.combined.tests".equals(old.target))agent.ui.dispatch(new JSONObject().put("op","close").put("session_id",old.taskId));if("os.aios.combined.tests".equals(agent.ui.foreground.target)){agent.ui.foreground.dispatch(new JSONObject().put("op","close"));agent.ui.foreground.pausedRequest="";}return null;});agent.ui.handler.post(clean);clean.get(15,java.util.concurrent.TimeUnit.SECONDS);c.getSharedPreferences("assistant_codex_threads",0).edit().putString("combined-lock-test",thread).commit();UiSessionManager.caller.set(thread);
  // Instrumentation restarts the target process, disconnecting its enabled accessibility service.
  String enabled=android.provider.Settings.Secure.getString(c.getContentResolver(),"enabled_accessibility_services");
  if(mode.equals("foreground")&&enabled!=null&&enabled.contains("os.aios.agent/")){
   android.app.UiAutomation automation=getUiAutomation(UiAutomation.FLAG_DONT_SUPPRESS_ACCESSIBILITY_SERVICES);automation.adoptShellPermissionIdentity("android.permission.WRITE_SECURE_SETTINGS");
   try{String filtered=String.join(":",java.util.Arrays.stream(enabled.split(":")).filter(x->!x.startsWith("os.aios.agent/")).toArray(String[]::new));android.provider.Settings.Secure.putString(c.getContentResolver(),"enabled_accessibility_services",filtered);Thread.sleep(300);android.provider.Settings.Secure.putString(c.getContentResolver(),"enabled_accessibility_services",enabled);}finally{automation.dropShellPermissionIdentity();}
   for(int i=0;i<40&&ForegroundUiService.instance==null;i++)Thread.sleep(200);
  }
  check(!c.getSystemService(KeyguardManager.class).isKeyguardLocked(),"starts unlocked");if(mode.equals("foreground")){testMain();result.putString("stream","PASS: "+assertions+" main-screen lock assertions\n"+log);return;}shell("input keyevent KEYCODE_HOME");for(int i=0;i<20&&"os.aios.combined.tests".equals(UiScreenContext.mainPackage(c));i++)Thread.sleep(200);Thread.sleep(500);create();JSONObject before=observe();int display=before.getInt("display_id");check(display>0,"background display is distinct from main");
  if(!mode.equals("auto"))shell("input keyevent KEYCODE_SLEEP");for(int i=0;i<90&&!c.getSystemService(KeyguardManager.class).isKeyguardLocked();i++)Thread.sleep(500);Thread.sleep(2200);check(c.getSystemService(KeyguardManager.class).isKeyguardLocked(),mode+" physical display locked");check(!c.getSystemService(PowerManager.class).isInteractive(),"physical display remains off");
  JSONObject tree=observe();check(tree.getInt("display_id")==display,"locked observation retains original display");JSONObject button=node(tree,"计数加一");JSONArray bounds=button.getJSONArray("bounds");java.util.regex.Matcher countMatch=java.util.regex.Pattern.compile("当前计数：([0-9]+)").matcher(tree.toString());if(!countMatch.find())throw new AssertionError("counter before missing");int previous=Integer.parseInt(countMatch.group(1));JSONObject input=agent.ui.call(new JSONObject().put("op","tap").put("session_id",id).put("observation_id",tree.getString("observation_id")).put("x",(bounds.getInt(0)+bounds.getInt(2))/2).put("y",(bounds.getInt(1)+bounds.getInt(3))/2));check(input.optBoolean("executed"),"locked background input executed");JSONObject after=observe();check(after.toString().contains("当前计数："+(previous+1)),"counter readable after locked input");
  Thread.sleep(15000);check(observe().getInt("display_id")==display,"offscreen observation survives 15 second interval");call("close");id="";create();check(observe().getInt("display_id")>0,"new virtual session can be created while locked");
  JSONObject main=agent.ui.foreground.create(new JSONObject().put("package","os.aios.combined.tests").put("_caller_thread",thread));check("device_locked".equals(main.optString("state")),"main screen creation blocked while locked");
  result.putString("stream","PASS: "+assertions+" real-device lock assertions\n"+log);
 }catch(Throwable e){result.putString("stream","FAIL: "+log+android.util.Log.getStackTraceString(e));code=0;}finally{UiSessionManager.caller.remove();try{if(agent!=null&&!id.isEmpty())call("close");}catch(Exception ignored){}UiSessionManager.caller.remove();c.getSharedPreferences("assistant_codex_threads",0).edit().remove("combined-lock-test").commit();finish(code,result);}}
}
